local buf, win = H.open()
vim.cmd("2Revisa comment")
H.reserved(buf, win, 2)
vim.cmd("close!")
assert(not H.padding(buf), "padding remains after closing the window")
vim.cmd("2Revisa comment")
local editor = H.reserved(buf, win, 2)
vim.api.nvim_buf_delete(editor, { force = true })
assert(not H.padding(buf), "padding remains after deleting the editor")
